-- Southern Barrens, the Battlescar: the fliers hang still in the sky and the patrols stand still
-- (Four, 2026-11-04: "we need to understand what this battle is ... what the NPC's should be doing").
--
-- The Battlescar spawns in our DB are the same spawns (same guids, same positions) as the MaNGOS
-- Three Cataclysm world DB, but MaNGOS Three has waypoint paths for 27 of them that our dump lost
-- (they were left at MovementType 0):
-- * 6 Desolation Wind Riders 37974 and 6 Triumph War Gryphons 37978: circling flight routes over the
--   Battlescar (33-54 points each, flown at run speed; both templates are InhabitType 4, fliers).
-- * 3 Desolation Raiders 37922, 2 Triumph Vanguards 37923, 5 Sapper Specialists 37925 (the ones
--   carrying aura 73457) and 5 stealthed Barrens Operatives 37924: short walking patrols (4-8 points).
--
-- The riders: 6 Desolation Sky Renders 37971 and 6 Wildhammer Mercenaries 37977 were spawned on their
-- own in mid-air (z 110-145, ground is ~95) with random movement; they are the passengers of the
-- wind riders and gryphons, seen mid-flight by the sniffer. The gryphon's own script already expects a
-- rider ("Passenger Boarded - Store Target 1", then on Hook Shot the Mercenary jumps down and attacks).
-- So the riders become vehicle accessories (seat 0) of their mounts and the 12 loose spawns go.
--
-- Path ids 485500001-485500027 are new.

DELETE FROM `waypoint_data` WHERE `id` BETWEEN 485500001 AND 485500999;
-- Path owners: 269007 (Desolation Wind Rider 485500001), 269009 (Desolation Wind Rider 485500002), 269011 (Desolation Wind Rider 485500003), 269013 (Desolation Wind Rider 485500004), 269015 (Desolation Wind Rider 485500005), 269017 (Desolation Wind Rider 485500006), 269019 (Triumph War Gryphon 485500007), 270158 (Triumph War Gryphon 485500008), 270332 (Triumph War Gryphon 485500009), 270334 (Triumph War Gryphon 485500010), 270343 (Triumph War Gryphon 485500011), 270347 (Triumph War Gryphon 485500012), 269585 (Desolation Raider 485500013), 270589 (Desolation Raider 485500014), 270667 (Desolation Raider 485500015), 269077 (Triumph Vanguard 485500016), 270905 (Triumph Vanguard 485500017), 270711 (Sapper Specialist 485500018), 270780 (Sapper Specialist 485500019), 270827 (Sapper Specialist 485500020), 270850 (Sapper Specialist 485500021), 270851 (Sapper Specialist 485500022), 269147 (Barrens Operative 485500023), 269148 (Barrens Operative 485500024), 269149 (Barrens Operative 485500025), 270197 (Barrens Operative 485500026), 270336 (Barrens Operative 485500027)
UPDATE `creature` SET `MovementType` = 2, `spawndist` = 0, `currentwaypoint` = 0 WHERE `guid` IN (269007, 269009, 269011, 269013, 269015, 269017, 269019, 270158, 270332, 270334, 270343, 270347, 269585, 270589, 270667, 269077, 270905, 270711, 270780, 270827, 270850, 270851, 269147, 269148, 269149, 270197, 270336);
ON DUPLICATE KEY UPDATE `path_id` = VALUES(`path_id`);

-- Riders on their mounts.
DELETE FROM `vehicle_template_accessory` WHERE `entry` IN (37974, 37978) AND `seat_id` = 0;
-- The loose mid-air riders (Kalimdor only; the stray Mercenary 200478 in the Eastern Kingdoms is left alone).
DELETE FROM `creature_addon` WHERE `guid` IN (269008, 269010, 269012, 269014, 269016, 269018, 269020, 270159, 270333, 270335, 270344, 270348);
DELETE FROM `creature` WHERE `guid` IN (269008, 269010, 269012, 269014, 269016, 269018, 269020, 270159, 270333, 270335, 270344, 270348) AND `id` IN (37971, 37977) AND `map` = 1;
